suppressPackageStartupMessages(library(edgeR));suppressPackageStartupMessages(library(limma))
r <- '/mnt/BioDisk/wangmingyuan/GI_preanalysis_20260923';o<-file.path(r,'04_results','GC_bulk');dir.create(o,recursive=TRUE,showWarnings=FALSE)
x<-read.delim(gzfile(file.path(r,'02_raw','GSE314812_counts.tsv.gz')),check.names=FALSE)
meta<-read.delim(file.path(r,'01_metadata','GSE314812_paired_design.tsv'),check.names=FALSE);meta<-meta[order(meta$patient,meta$site),]
cnt<-as.matrix(x[,meta$sample]);storage.mode(cnt)<-'numeric';rownames(cnt)<-x$gene_id;stopifnot(!anyNA(cnt),all(cnt>=0),!anyDuplicated(rownames(cnt)))
meta$patient<-factor(meta$patient);meta$site<-factor(meta$site,levels=c('GCPT','GCPM'));meta$preservation<-factor(meta[['preservation method']])
design<-model.matrix(~patient+preservation+site,data=meta);stopifnot(qr(design)$rank==ncol(design))
d<-DGEList(cnt);keep<-filterByExpr(d,design=design);d<-calcNormFactors(d[keep,,keep.lib.sizes=FALSE]);v<-voom(d,design,plot=FALSE);fit<-eBayes(lmFit(v,design));res<-topTable(fit,coef='siteGCPM',number=Inf,sort.by='none')
ann<-read.delim(file.path(r,'01_metadata','human_gene_symbols_from_GSE145356.tsv'));ann<-ann[!duplicated(ann$gene_id),];symbols<-ann$symbol[match(rownames(v$E),ann$gene_id)]
res$gene_id<-rownames(res);res$symbol<-symbols
# Observed paired effects and consistency
ids<-levels(meta$patient);delta<-sapply(ids,function(id){v$E[,meta$patient==id&meta$site=='GCPM']-v$E[,meta$patient==id&meta$site=='GCPT']})
res$positive_pairs<-rowSums(delta>0);res$negative_pairs<-rowSums(delta<0);res$median_observed_paired_log2CPM_difference<-apply(delta,1,median)
write.table(res,file.path(o,'paired_preservation_adjusted_DE.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
write.table(data.frame(gene_id=rownames(delta),symbol=symbols,delta),gzfile(file.path(o,'paired_gene_effects.tsv.gz')),sep='\t',row.names=FALSE,quote=FALSE)
meta$raw_library_size<-colSums(cnt);meta$detected_genes<-colSums(cnt>0);meta$TMM_factor<-d$samples$norm.factors;write.table(meta,file.path(o,'paired_sample_qc.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
write.table(data.frame(gene_id=rownames(v$E),symbol=symbols,v$E),gzfile(file.path(r,'03_processed','GC314812_TMM_logCPM.tsv.gz')),sep='\t',row.names=FALSE,quote=FALSE)
panels<-list(Lipid_synthesis=c('FASN','ACACA','SCD','ACLY','SREBF1','ELOVL6','FADS2'),Lipid_uptake=c('CD36','FABP4','FABP5','SLC27A1','SLC27A2','SLC27A4','LDLR','LPL'),FAO=c('CPT1A','CPT2','ACADM','ACADL','HADHA','HADHB','ACOX1'),Adhesion=c('ITGA5','ITGB1','ITGAV','ITGB3','CDH1','CD44','PTK2','PXN','VCL'),Cell_cycle=c('MKI67','PCNA','MCM2','MCM3','MCM4','MCM5','MCM6','MCM7','TOP2A','CCNB1','CDK1'),Stress_response=c('ATF3','ATF4','DDIT3','DDIT4','HSPA5','HMOX1','NQO1','TXNIP'),YAP_regeneration=c('YAP1','WWTR1','CTGF','CCN2','CYR61','CCN1','ANKRD1','CLDN4','TACSTD2'),Autophagy=c('ATG5','ATG7','BECN1','MAP1LC3B','SQSTM1','LAMP1','LAMP2','TFEB'))
scores<-sapply(panels,function(gs)colMeans(v$E[symbols%in%gs,,drop=FALSE]));rownames(scores)<-meta$sample
coverage<-data.frame(panel=names(panels),genes_planned=sapply(panels,length),genes_measured=sapply(panels,function(gs)sum(symbols%in%gs)),measured_symbols=sapply(panels,function(gs)paste(symbols[symbols%in%gs],collapse=';')))
write.table(coverage,file.path(o,'diagnostic_panel_coverage.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
pr<-lapply(colnames(scores),function(p){z<-coef(summary(lm(scores[,p]~patient+preservation+site,data=meta)))['siteGCPM',];dif<-sapply(ids,function(id)scores[meta$patient==id&meta$site=='GCPM',p]-scores[meta$patient==id&meta$site=='GCPT',p]);data.frame(panel=p,adjusted_mean_log2CPM_difference=z[1],SE=z[2],P=z[4],positive_pairs=sum(dif>0),negative_pairs=sum(dif<0),median_observed_paired_difference=median(dif))});pr<-do.call(rbind,pr);pr$FDR_BH<-p.adjust(pr$P,'BH');write.table(pr,file.path(o,'diagnostic_panel_statistics.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
write.table(data.frame(sample=rownames(scores),scores),file.path(o,'diagnostic_panel_sample_scores.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
# Composition sensitivity is an explicitly separate model, not an additional discovery family.
cs<-sapply(list(stroma=c('COL1A1','COL1A2','COL3A1','DCN','LUM','FAP','PDGFRA'),immune=c('PTPRC','CD3D','CD3E','LST1','TYROBP','CD68')),function(gs)colMeans(v$E[symbols%in%gs,,drop=FALSE]));meta$stroma_score<-cs[,'stroma'];meta$immune_score<-cs[,'immune']
des2<-model.matrix(~patient+preservation+stroma_score+immune_score+site,data=meta);stopifnot(qr(des2)$rank==ncol(des2));v2<-voom(d,des2,plot=FALSE);f2<-eBayes(lmFit(v2,des2));s2<-topTable(f2,coef='siteGCPM',number=Inf,sort.by='none');s2$gene_id<-rownames(s2);s2$symbol<-symbols;write.table(s2,file.path(o,'composition_sensitivity_DE.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
ps<-lapply(colnames(scores),function(p){z<-coef(summary(lm(scores[,p]~patient+preservation+stroma_score+immune_score+site,data=meta)))['siteGCPM',];data.frame(panel=p,adjusted_difference=z[1],SE=z[2],P=z[4])});ps<-do.call(rbind,ps);ps$FDR_BH<-p.adjust(ps$P,'BH');write.table(ps,file.path(o,'composition_sensitivity_panels.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
# Fresh-frozen matched subset: effect directions only if below 10 patients.
ff<-ids[sapply(ids,function(id)all(meta$preservation[meta$patient==id]=='fresh-frozen'))];ff_eff<-if(length(ff))rowMeans(delta[,ff,drop=FALSE]) else rep(NA_real_,nrow(delta));write.table(data.frame(gene_id=rownames(delta),symbol=symbols,n_pairs=length(ff),mean_paired_log2CPM_difference=ff_eff),file.path(o,'fresh_frozen_pair_effects.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
# Sensitivity excluding the serially sampled patient GC05.
k<-meta$patient!='GC05';m3<-droplevels(meta[k,]);d3<-calcNormFactors(d[,k]);de3<-model.matrix(~patient+preservation+site,m3);v3<-voom(d3,de3,plot=FALSE);rr<-topTable(eBayes(lmFit(v3,de3)),coef='siteGCPM',number=Inf,sort.by='none');rr$gene_id<-rownames(rr);rr$symbol<-symbols;write.table(rr,file.path(o,'exclude_GC05_sensitivity_DE.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
p<-prcomp(t(v$E[order(apply(v$E,1,var),decreasing=TRUE)[1:2000],]));write.table(data.frame(sample=rownames(p$x),patient=meta$patient,site=meta$site,preservation=meta$preservation,p$x[,1:3]),file.path(o,'PCA.tsv'),sep='\t',row.names=FALSE,quote=FALSE)
summary<-c(input_genes=nrow(cnt),tested_genes=nrow(res),independent_pairs=length(ids),libraries=ncol(cnt),design_rank=qr(design)$rank,residual_df=nrow(design)-ncol(design),gene_FDR_lt005=sum(res$adj.P.Val<.05),gene_FDR_lt005_abslogFC_ge1=sum(res$adj.P.Val<.05&abs(res$logFC)>=1),fresh_frozen_pairs=length(ff),composition_gene_FDR_lt005=sum(s2$adj.P.Val<.05))
write.table(data.frame(metric=names(summary),value=summary),file.path(o,'summary.tsv'),sep='\t',row.names=FALSE,quote=FALSE);capture.output(sessionInfo(),file=file.path(r,'logs','GC_bulk_R_sessionInfo.txt'));writeLines('exit_code=0; paired_design_full_rank; outputs_written',file.path(o,'COMPLETE.txt'));print(summary);print(pr)
